CREATE TABLE public.engineering_workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, scope text NOT NULL, name text NOT NULL, environment text NOT NULL DEFAULT 'sandbox' CHECK (environment IN ('sandbox','production')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,scope));
GRANT SELECT,INSERT ON public.engineering_workspaces TO authenticated;
GRANT ALL ON public.engineering_workspaces TO service_role;
ALTER TABLE public.engineering_workspaces ENABLE ROW LEVEL SECURITY;
CREATE POLICY workspace_owner_read ON public.engineering_workspaces FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE POLICY sandbox_workspace_create ON public.engineering_workspaces FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND environment='sandbox');
CREATE TABLE public.engineering_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.engineering_workspaces(id), revision integer NOT NULL CHECK(revision>0), payload jsonb NOT NULL, lifecycle text NOT NULL DEFAULT 'Draft' CHECK(lifecycle IN ('Draft','In Review','Approved')), actor_id uuid NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,revision));
GRANT SELECT,INSERT ON public.engineering_revisions TO authenticated;
GRANT ALL ON public.engineering_revisions TO service_role;
ALTER TABLE public.engineering_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY revisions_owner_read ON public.engineering_revisions FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.engineering_workspaces w WHERE w.id=workspace_id AND w.owner_id=auth.uid()));
CREATE TABLE public.engineering_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES public.engineering_workspaces(id), revision_id uuid NOT NULL REFERENCES public.engineering_revisions(id), actor_id uuid NOT NULL, action text NOT NULL, reason text NOT NULL, before_revision integer, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.engineering_audit TO authenticated;
GRANT ALL ON public.engineering_audit TO service_role;
ALTER TABLE public.engineering_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_owner_read ON public.engineering_audit FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.engineering_workspaces w WHERE w.id=workspace_id AND w.owner_id=auth.uid()));
CREATE FUNCTION public.save_engineering_revision(p_workspace uuid,p_expected integer,p_payload jsonb,p_reason text,p_lifecycle text DEFAULT 'Draft') RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE latest integer; rid uuid; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM engineering_workspaces WHERE id=p_workspace AND owner_id=auth.uid() AND environment='sandbox') THEN RAISE EXCEPTION 'Forbidden'; END IF; PERFORM 1 FROM engineering_workspaces WHERE id=p_workspace FOR UPDATE; SELECT COALESCE(max(revision),0) INTO latest FROM engineering_revisions WHERE workspace_id=p_workspace; IF latest<>p_expected THEN RAISE EXCEPTION 'Revision conflict: reload before saving'; END IF; IF length(trim(p_reason))<3 OR p_lifecycle NOT IN ('Draft','In Review') OR jsonb_typeof(p_payload)<>'object' THEN RAISE EXCEPTION 'Invalid revision'; END IF; INSERT INTO engineering_revisions(workspace_id,revision,payload,actor_id,reason,lifecycle) VALUES(p_workspace,latest+1,p_payload,auth.uid(),p_reason,p_lifecycle) RETURNING id INTO rid; INSERT INTO engineering_audit(workspace_id,revision_id,actor_id,action,reason,before_revision) VALUES(p_workspace,rid,auth.uid(),p_lifecycle,p_reason,latest); RETURN latest+1; END; $$;
REVOKE ALL ON FUNCTION public.save_engineering_revision(uuid,integer,jsonb,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_engineering_revision(uuid,integer,jsonb,text,text) TO authenticated;